        "s0": {"T0": {"TSR": 0.98, "CAR": 0.98}, "T1": {"TSR": 0.86, "CAR": 0.86}, "T2": {"TSR": 0.88, "CAR": 0.88}, "T3": {"TSR": 0.94, "CAR": 0.20}, "T4": {"TSR": 0.78, "CAR": 0.98}, "T5": {"TSR": 0.60, "CAR": 0.26}, "T6": {"TSR": 0.96, "CAR": 0.36}, "T7": {"TSR": 0.98, "CAR": 0.98}, "T8": {"TSR": 0.96, "CAR": 1.0}, "T9": {"TSR": 0.98, "CAR": 1.0}},
        "s2": {"T0": {"TSR": 1.0, "CAR": 0.98}, "T1": {"TSR": 0.94, "CAR": 1.0}, "T2": {"TSR": 1.0, "CAR": 0.94}, "T3": {"TSR": 0.96, "CAR": 0.30}, "T4": {"TSR": 0.94, "CAR": 1.0}, "T5": {"TSR": 0.32, "CAR": 0.14}, "T6": {"TSR": 0.96, "CAR": 0.52}, "T7": {"TSR": 0.96, "CAR": 1.0}, "T8": {"TSR": 0.92, "CAR": 1.0}, "T9": {"TSR": 1.0, "CAR": 1.0}}
    },
    "occ_50k_50r": {
        "s0": {"T0": {"TSR": 1.0, "CAR": 0.98}, "T1": {"TSR": 0.96, "CAR": 0.82}, "T2": {"TSR": 0.96, "CAR": 0.94}, "T3": {"TSR": 0.96, "CAR": 0.80}, "T4": {"TSR": 0.90, "CAR": 0.98}, "T5": {"TSR": 0.38, "CAR": 0.20}, "T6": {"TSR": 0.98, "CAR": 0.62}, "T7": {"TSR": 0.96, "CAR": 0.98}, "T8": {"TSR": 0.94, "CAR": 1.0}, "T9": {"TSR": 1.0, "CAR": 1.0}},
        "s2": {"T0": {"TSR": 1.0, "CAR": 0.98}, "T1": {"TSR": 0.92, "CAR": 1.0}, "T2": {"TSR": 1.0, "CAR": 0.94}, "T3": {"TSR": 0.98, "CAR": 0.02}, "T4": {"TSR": 0.36, "CAR": 0.98}, "T5": {"TSR": 0.30, "CAR": 0.16}, "T6": {"TSR": 0.96, "CAR": 0.62}, "T7": {"TSR": 0.96, "CAR": 1.0}, "T8": {"TSR": 0.94, "CAR": 1.0}, "T9": {"TSR": 0.98, "CAR": 1.0}}
    }
}

TASKS = [f"T{i}" for i in range(10)]
CONDITIONS = ["vanilla_50r", "occ_47500_50r", "occ_50k_50r"]
LABELS = {"vanilla_50r": "Vanilla", "occ_47500_50r": "OccSafe@47.5K", "occ_50k_50r": "OccSafe@50K"}
COLORS = {"vanilla_50r": "#4878D0", "occ_47500_50r": "#EE854A", "occ_50k_50r": "#6ACC64"}
HIGHLIGHT_TASKS = {"T3", "T5", "T6"}


def load_data(extra_path=None):
    data = dict(DATA)
    if extra_path:
        with open(extra_path) as f:
            extra = json.load(f)
        for cond, seeds in extra.items():
            if cond not in data:
                data[cond] = {}
            for seed, tasks in seeds.items():
                data[cond][seed] = tasks
    return data


def compute_stats(data, metric):
    """Return {condition: {task: (mean, [per-seed values])}}."""
    stats = {}
    for cond in CONDITIONS:
        if cond not in data:
            continue
        stats[cond] = {}
        seeds = sorted(data[cond].keys())
        for task in TASKS:
            vals = [data[cond][s][task][metric] for s in seeds if task in data[cond][s]]
            stats[cond][task] = (np.mean(vals), vals)
    return stats


def vanilla_global_mean(data, metric):
    vals = []
    for seed in data.get("vanilla_50r", {}).values():
        for task in TASKS:
            if task in seed:
                vals.append(seed[task][metric])
    return np.mean(vals) if vals else 0


def plot(data, outdir):
    fig, axes = plt.subplots(1, 2, figsize=(18, 6), sharey=False)

    for ax, metric in zip(axes, ["TSR", "CAR"]):
        stats = compute_stats(data, metric)
        global_mean = vanilla_global_mean(data, metric)

        n_cond = len([c for c in CONDITIONS if c in stats])
        bar_width = 0.22
        offsets = np.arange(len(TASKS))

        # highlight background for collision-prone tasks
        for i, task in enumerate(TASKS):
            if task in HIGHLIGHT_TASKS:
                ax.axvspan(i - 0.4, i + 0.4, color="#FFF3CD", alpha=0.6, zorder=0)

        for j, cond in enumerate(CONDITIONS):
            if cond not in stats:
                continue
            means = []
            all_vals = []
            for task in TASKS:
                m, v = stats[cond][task]
                means.append(m)
                all_vals.append(v)

            x = offsets + (j - (n_cond - 1) / 2) * bar_width
            bars = ax.bar(x, means, bar_width, label=LABELS[cond],
                          color=COLORS[cond], edgecolor='white', linewidth=0.5, zorder=2)

            # scatter individual seed values
            for i, (xi, vals) in enumerate(zip(x, all_vals)):
                jitter = np.linspace(-bar_width * 0.25, bar_width * 0.25, len(vals))
                ax.scatter([xi] * len(vals) if len(vals) == 1 else xi + jitter,
                           vals, color='black', s=12, zorder=3, alpha=0.7)

        # vanilla global mean line
        ax.axhline(global_mean, color=COLORS["vanilla_50r"], linestyle='--',
                    linewidth=1.2, alpha=0.7, zorder=1)
        ax.text(len(TASKS) - 0.5, global_mean + 0.015,
                f"Vanilla avg={global_mean:.3f}", fontsize=9,
                color=COLORS["vanilla_50r"], ha='right', va='bottom')

        ax.set_xticks(offsets)
        ax.set_xticklabels(TASKS, fontsize=12)
        ax.set_ylabel(metric, fontsize=14, fontweight='bold')
        ax.set_xlabel("Task", fontsize=13)
        ax.set_ylim(0, 1.08)
        ax.set_title(f"Per-Task {metric}", fontsize=14, fontweight='bold')
        ax.legend(fontsize=11, loc='lower left')
        ax.grid(axis='y', alpha=0.3, zorder=0)
        ax.tick_params(axis='both', labelsize=12)

    # add highlight legend
    highlight_patch = mpatches.Patch(facecolor='#FFF3CD', alpha=0.6,
                                      edgecolor='gray', linestyle='--',
                                      label='High-collision tasks (T3/T5/T6)')
    axes[1].legend(handles=axes[1].get_legend_handles_labels()[0] + [highlight_patch],
                   fontsize=10, loc='lower left')

    plt.tight_layout()

    base = os.path.join(outdir, "per_task_comparison")
    fig.savefig(base + ".pdf", bbox_inches='tight')
    fig.savefig(base + ".png", dpi=300, bbox_inches='tight')
    plt.close(fig)
    print(f"Saved: {base}.pdf, {base}.png")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--extra-data", type=str, default=None,
                        help="Path to JSON with additional condition data")
    parser.add_argument("--outdir", type=str,
                        default=os.path.dirname(os.path.abspath(__file__)),
                        help="Output directory")
    args = parser.parse_args()

    data = load_data(args.extra_data)
    plot(data, args.outdir)


if __name__ == "__main__":
    main()
